import { revalidateTag } from 'next/cache'
import { getProducts } from '@/lib/products'

export default async function Page() {
  const products = await getProducts()

  async function syncCatalog() {
    'use server'
    // Trigger upstream ERP/PIM sync here if needed.
    // Stale-while-revalidate: mark catalog data stale without blocking.
    // Admins keep seeing the current list while fresh data loads in the
    // background, and every view using the `products` tag updates shortly after.
    revalidateTag('products', 'max')
  }

  return (
    <main>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

